CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS publications(version TEXT PRIMARY KEY,published_at TEXT NOT NULL,source_sheet_id TEXT NOT NULL,item_count INTEGER NOT NULL,regulation_count INTEGER NOT NULL,document_count INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS items(version TEXT NOT NULL,id TEXT NOT NULL,jenis TEXT,kelompok TEXT,subkelompok TEXT,nama TEXT,definisi TEXT,satuan TEXT,status TEXT,PRIMARY KEY(version,id));
CREATE TABLE IF NOT EXISTS rates(version TEXT NOT NULL,id TEXT NOT NULL,item_id TEXT NOT NULL,tahun INTEGER,wilayah TEXT,kategori TEXT,besaran REAL,mata_uang TEXT,ketentuan TEXT,PRIMARY KEY(version,id));
CREATE TABLE IF NOT EXISTS regulations(version TEXT NOT NULL,id TEXT NOT NULL,jenis TEXT,nomor TEXT,tahun INTEGER,judul TEXT,tanggal_berlaku TEXT,status TEXT,url TEXT,PRIMARY KEY(version,id));
CREATE TABLE IF NOT EXISTS item_regulations(version TEXT NOT NULL,item_id TEXT NOT NULL,regulation_id TEXT NOT NULL,pasal TEXT,lampiran TEXT,halaman TEXT,keterangan TEXT);
CREATE TABLE IF NOT EXISTS documents(version TEXT NOT NULL,id TEXT NOT NULL,judul TEXT,kategori TEXT,tahun INTEGER,deskripsi TEXT,drive_file_id TEXT,status_publikasi TEXT,PRIMARY KEY(version,id));
CREATE TABLE IF NOT EXISTS faqs(version TEXT NOT NULL,id TEXT NOT NULL,pertanyaan TEXT,jawaban TEXT,referensi TEXT,status TEXT,PRIMARY KEY(version,id));
CREATE TABLE IF NOT EXISTS sync_logs(id TEXT PRIMARY KEY,started_at TEXT,completed_at TEXT,status TEXT,message TEXT,publication_version TEXT);
CREATE INDEX IF NOT EXISTS idx_items_search ON items(version,jenis,nama);
CREATE INDEX IF NOT EXISTS idx_rates_item ON rates(version,item_id);
